import{_ as n,o as r,c as i,a3 as u}from"./chunks/framework.z_KJ15Ep.js";const m=JSON.parse('{"title":"Zeugnisformulare und Archivierung","description":"","frontmatter":{},"headers":[],"relativePath":"reporting/zeugnisformulare.md","filePath":"reporting/zeugnisformulare.md"}'),a={name:"reporting/zeugnisformulare.md"};function t(l,e,s,o,h,d){return r(),i("div",null,[...e[0]||(e[0]=[u('<h1 id="zeugnisformulare-und-archivierung" tabindex="-1">Zeugnisformulare und Archivierung <a class="header-anchor" href="#zeugnisformulare-und-archivierung" aria-label="Permalink to &quot;Zeugnisformulare und Archivierung&quot;">​</a></h1><p>Stellen Sie die Zeugnisformulare Ihrer Schulform bereit und konfigurieren Sie die verwendeten Anlagen. Bewahren Sie die zum Lernabschnitt gehörenden Formulare für Nachdrucke auf.</p><h2 id="formulare-bereitstellen-und-konfigurieren" tabindex="-1">Formulare bereitstellen und konfigurieren <a class="header-anchor" href="#formulare-bereitstellen-und-konfigurieren" aria-label="Permalink to &quot;Formulare bereitstellen und konfigurieren&quot;">​</a></h2><ol><li>Wählen Sie das passende Paket: <a href="/reporting/zeugnisformulare/zeugnispakete-auf-github.html">Zeugnispakete nach Schulform auswählen</a>.</li><li>Entpacken Sie die Formulare in die Reportstruktur: <a href="/reporting/zeugnisformulare/zeugnisformulare-herunterladen-und-aktualisieren.html">Zeugnisformulare herunterladen und bereitstellen</a>.</li><li>Passen Sie die zugehörige Datei <code>Zeugniseinstellungen.ini</code> je Anlage an: <a href="/reporting/zeugnisformulare/inhalt-layout-von-zeugnissen-konfigurieren.html">Inhalt und Layout von Zeugnissen konfigurieren</a>.</li></ol><p>Die <a href="/reporting/zeugnisformulare/zeugnisse-themenuebersicht.html">Übersicht zum Zeugnisdruck</a> führt außerdem zu schulformspezifischen Anleitungen, Gruppendruck und Broschürendruck.</p><h2 id="dokumente-und-zeugnisse-archivieren" tabindex="-1">Dokumente und Zeugnisse archivieren <a class="header-anchor" href="#dokumente-und-zeugnisse-archivieren" aria-label="Permalink to &quot;Dokumente und Zeugnisse archivieren&quot;">​</a></h2><ul><li>Ablagen einrichten, Benennung wählen und Ausgaben speichern: <a href="/reporting/zeugnisformulare/dokumentenverwaltung-und-zeugnisarchivierung.html">Reportausgaben und Zeugnisse archivieren</a>.</li><li>Einen bestehenden Ablageort ändern: <a href="/reporting/reportdesigner/verzeichnis-der-dokumentenverwaltung-aendern-tutorial.html">Das Verzeichnis der Dokumentenablage ändern</a>.</li></ul><p>Beachten Sie die unterschiedlichen Namensregeln von Dokumentenablage und Zeugnisverzeichnis. Ältere Zeugnisstände werden nicht in jedem Verfahren automatisch unter einem neuen Dateinamen erhalten.</p><h2 id="mahnungsdruck-vorbereiten" tabindex="-1">Mahnungsdruck vorbereiten <a class="header-anchor" href="#mahnungsdruck-vorbereiten" aria-label="Permalink to &quot;Mahnungsdruck vorbereiten&quot;">​</a></h2><p>Der Gruppenprozess <a href="/reporting/zeugnisformulare/mahnungsdruck-einleiten-gruppenprozesse-noten-zeugnisvorbereitung.html">Mahnungsdruck einleiten</a> führt zur passenden Schülerauswahl. Den vollständigen Ablauf erläutert <a href="/reporting/reportdesigner/mahnbriefe-drucken-tutorial.html">Mahnbriefe drucken</a> im Bereich Serienbriefe.</p>',10)])])}const c=n(a,[["render",t]]);export{m as __pageData,c as default};
